/**
 * Normalizes any legacy or semantic USMLE subject identifier to its canonical semantic form.
 */
export function normalizeUsmleSubjectId(id: string | number | undefined | null): string {
  if (!id) return '';
  const strId = String(id);
  return USMLE_LEGACY_ID_MAP[strId] || strId;
}

/**
 * Normalizes a legacy system identifier (e.g., 'USMLE_1_1' -> 'USMLE_CVS_1').
 */
export function normalizeUsmleSystemId(systemId: string | number | undefined | null): string {
  if (!systemId) return '';
  const strId = String(systemId);
  return USMLE_SYSTEM_ID_MAP[strId] || strId;
}

/**
 * Normalizes a legacy topic identifier (e.g., 'USMLE_1_1_001' -> 'USMLE_CVS_1_001').
 */
export function normalizeUsmleTopicId(topicId: string | number | undefined | null): string {
  if (!topicId) return '';
  const strId = String(topicId);
  const match = strId.match(/^USMLE_(\d+)_(\d+)_(\d+)$/);
  if (match) {
    const sysLegacy = `USMLE_${match[1]}_${match[2]}`;
    const newSys = USMLE_SYSTEM_ID_MAP[sysLegacy];
    if (newSys) {
      return `${newSys}_${match[3]}`;
    }
  }
  return strId;
}

/**
 * Checks if two subject IDs match, accounting for legacy mapping and aliases.
 */
export function isSubjectIdMatch(idA: string | number | undefined | null, idB: string | number | undefined | null): boolean {
  if (!idA || !idB) return false;
  if (String(idA) === String(idB)) return true;
  const normA = normalizeUsmleSubjectId(idA);
  const normB = normalizeUsmleSubjectId(idB);
  if (normA && normB && normA === normB) return true;
  const revA = USMLE_REVERSE_LEGACY_MAP[normA] || [];
  if (revA.includes(String(idB))) return true;
  const revB = USMLE_REVERSE_LEGACY_MAP[normB] || [];
  if (revB.includes(String(idA))) return true;
  return false;
}

